-- CT11b staged only, generated by pinned CLI run #45520533397.
-- Revoke legacy direct layout writes; cut over application and migration together.
begin;
create table newsroom_private.homepage_revision(
 singleton boolean primary key default true check(singleton),
 revision integer not null default 0 check(revision>=0)
);
insert into newsroom_private.homepage_revision(singleton,revision) values(true,0);
create table newsroom_private.homepage_versions(
 revision integer primary key check(revision>=0),
 selections jsonb not null check(jsonb_typeof(selections)='array' and jsonb_array_length(selections)<=100),
 published_at timestamptz not null default clock_timestamp(),
 actor uuid,
 baseline boolean not null default false,
 check((revision=0)=baseline),check((actor is null)=baseline)
);
alter table newsroom_private.homepage_revision enable row level security;
alter table newsroom_private.homepage_versions enable row level security;
revoke all on newsroom_private.homepage_revision,newsroom_private.homepage_versions from public,anon,authenticated,service_role;
revoke insert,update,delete,truncate on public.homepage_slots,public.homepage_layout_drafts from public,anon,authenticated;
revoke execute on function public.publish_homepage_layout(jsonb,uuid) from public,anon,authenticated,service_role;
create function newsroom_private.homepage_editor_allowed(p_publish boolean)
returns boolean language sql stable security invoker set search_path='' as $fn$
 select coalesce(public.staff_invite_verified_identity((select auth.uid())),false)
 and newsroom_private.has_staff_permission('newsroom.access')
 and newsroom_private.has_staff_permission('homepage.view_editor')
 and newsroom_private.has_staff_permission('homepage.edit')
 and (not p_publish or newsroom_private.has_staff_permission('homepage.publish'))
$fn$;
create function newsroom_private.homepage_live_selections()
returns jsonb language sql stable security invoker set search_path='' as $fn$
 select coalesce(jsonb_agg(jsonb_build_object('slot',s.slot,'position',s.position,'storyId',s.story_id,'categoryId',s.category_id) order by s.slot,s.position,s.story_id),'[]'::jsonb)
 from public.homepage_slots s where s.active
$fn$;
create function newsroom_private.homepage_legacy_blocked()
returns boolean language sql stable security invoker set search_path='' as $fn$
 select exists(select 1 from public.homepage_slots where not active or starts_at is not null or ends_at is not null)
 or (select count(*) from public.homepage_slots)>100
$fn$;
create function newsroom_private.validate_homepage_selections(p_copy jsonb)
returns void language plpgsql security invoker set search_path='' as $fn$
declare item jsonb; v_story uuid; v_slot public.homepage_slot_type; v_category uuid; v_position integer;
begin
 if p_copy is null or jsonb_typeof(p_copy)<>'array' then raise exception 'Invalid layout' using errcode='22023';end if;
 if jsonb_array_length(p_copy)>100 then raise exception 'Layout too large' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(p_copy) loop
  if jsonb_typeof(item)<>'object' then raise exception 'Invalid selection' using errcode='22023';end if;
  if (select count(*) from jsonb_object_keys(item))<>4 or not (item ?& array['slot','position','storyId','categoryId'])
   or jsonb_typeof(item->'slot')<>'string' or jsonb_typeof(item->'storyId')<>'string'
   or jsonb_typeof(item->'position')<>'number' or jsonb_typeof(item->'categoryId') not in ('string','null')
   or item->>'position' !~ '^[0-9]{1,3}$' then raise exception 'Invalid selection' using errcode='22023';end if;
  begin
   v_slot:=(item->>'slot')::public.homepage_slot_type;
   v_story:=(item->>'storyId')::uuid;
   v_category:=(item->>'categoryId')::uuid;
   v_position:=(item->>'position')::integer;
  exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'Invalid selection' using errcode='22023';end;
  if v_position>199 or v_story is null or v_slot is null then raise exception 'Invalid selection' using errcode='22023';end if;
  -- Lock referenced stories until the layout transaction completes.
  perform 1 from public.stories s where s.id=v_story and s.status='published' and s.published_at is not null and s.published_at<=statement_timestamp() for share;
  if not found then raise exception 'Selection is no longer published' using errcode='40001';end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_copy) x group by x->>'slot',(x->>'position')::integer having count(*)>1)
 or exists(select 1 from jsonb_array_elements(p_copy) x group by ((x->>'slot')='headline_bar'),(x->>'storyId')::uuid having count(*)>1)
 then raise exception 'Duplicate layout selection' using errcode='22023';end if;
end;
$fn$;
create function newsroom_private.read_homepage_versioned()
returns jsonb language plpgsql stable security definer set search_path='' set timezone='UTC' as $fn$
declare v_revision integer;v_live jsonb;v_draft jsonb;v_at timestamptz;v_history jsonb;
begin
 if not newsroom_private.homepage_editor_allowed(false) then raise exception 'Layout access denied' using errcode='42501';end if;
 select revision into v_revision from newsroom_private.homepage_revision where singleton;
 v_live:=newsroom_private.homepage_live_selections();
 select selections,updated_at into v_draft,v_at from public.homepage_layout_drafts where id='current';
 select coalesce(jsonb_agg(jsonb_build_object('revision',h.revision,'publishedAt',h.published_at,'baseline',h.baseline,'slotCount',jsonb_array_length(h.selections)) order by h.revision desc),'[]'::jsonb) into v_history
 from (select * from newsroom_private.homepage_versions order by revision desc limit 20) h;
 return jsonb_build_object('revision',v_revision,'published',v_live,'selections',coalesce(v_draft,v_live),'updatedAt',v_at,'history',v_history,'legacyBlocked',newsroom_private.homepage_legacy_blocked());
end;
$fn$;
create function newsroom_private.change_homepage_versioned(p_action text,p_expected integer,p_copy jsonb,p_restore integer)
returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' as $fn$
declare v_revision integer;v_live jsonb;v_copy jsonb;v_actor uuid:=(select auth.uid());v_at timestamptz:=clock_timestamp();
begin
 if p_action is null or p_action not in ('save','publish','revert','restore') or p_expected is null or p_expected<0
 or (p_action in ('save','publish') and (p_copy is null or p_restore is not null))
 or (p_action='restore' and (p_restore is null or p_restore<0 or p_copy is not null))
 or (p_action='revert' and (p_copy is not null or p_restore is not null)) then raise exception 'Invalid layout command' using errcode='22023';end if;
 if not newsroom_private.homepage_editor_allowed(p_action='publish') then raise exception 'Layout access denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(202611,2302);
 if not newsroom_private.homepage_editor_allowed(p_action='publish') then raise exception 'Layout access denied' using errcode='42501';end if;
 select revision into v_revision from newsroom_private.homepage_revision where singleton for update;
 if v_revision is distinct from p_expected then raise exception 'Layout changed' using errcode='40001';end if;
 if newsroom_private.homepage_legacy_blocked() then raise exception 'Legacy timed or inactive placements require reconciliation' using errcode='40001';end if;
 v_live:=newsroom_private.homepage_live_selections();
 if p_action='revert' then v_copy:=v_live;
 elsif p_action='restore' then
  select selections into v_copy from newsroom_private.homepage_versions where revision=p_restore;
  if not found then raise exception 'Version unavailable' using errcode='22023';end if;
 else v_copy:=p_copy;end if;
 perform newsroom_private.validate_homepage_selections(v_copy);
 if p_action='publish' then
  if not exists(select 1 from newsroom_private.homepage_versions) then
   insert into newsroom_private.homepage_versions(revision,selections,baseline) values(0,v_live,true);
  end if;
  delete from public.homepage_slots where true;
  insert into public.homepage_slots(slot,story_id,position,category_id,active,created_by,updated_by)
   select (x->>'slot')::public.homepage_slot_type,(x->>'storyId')::uuid,(x->>'position')::integer,(x->>'categoryId')::uuid,true,v_actor,v_actor from jsonb_array_elements(v_copy) x;
  insert into newsroom_private.homepage_versions(revision,selections,actor) values(v_revision+1,v_copy,v_actor);
 end if;
 insert into public.homepage_layout_drafts(id,selections,updated_by,updated_at) values('current',v_copy,v_actor,v_at)
 on conflict(id) do update set selections=excluded.selections,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
 update newsroom_private.homepage_revision set revision=v_revision+1 where singleton;
 return newsroom_private.read_homepage_versioned();
end;
$fn$;
create function public.staff_read_homepage_versioned() returns jsonb language sql stable security invoker set search_path='' return newsroom_private.read_homepage_versioned();
create function public.staff_change_homepage_versioned(p_action text,p_expected integer,p_copy jsonb,p_restore integer) returns jsonb language sql security invoker set search_path='' return newsroom_private.change_homepage_versioned(p_action,p_expected,p_copy,p_restore);
revoke all on function newsroom_private.homepage_editor_allowed(boolean),newsroom_private.homepage_live_selections(),newsroom_private.homepage_legacy_blocked(),newsroom_private.validate_homepage_selections(jsonb),newsroom_private.read_homepage_versioned(),newsroom_private.change_homepage_versioned(text,integer,jsonb,integer),public.staff_read_homepage_versioned(),public.staff_change_homepage_versioned(text,integer,jsonb,integer) from public,anon,authenticated,service_role;
grant execute on function newsroom_private.read_homepage_versioned(),newsroom_private.change_homepage_versioned(text,integer,jsonb,integer),public.staff_read_homepage_versioned(),public.staff_change_homepage_versioned(text,integer,jsonb,integer) to authenticated;
commit;
